{
  "request": "SELECT c.customer_id, c.company_name, s.billing_cycle, s.monthly_rate, SUM(i.downtime_minutes) AS total_downtime, COUNT(i.incident_id) AS incident_count FROM customers c JOIN subscriptions s ON c.customer_id = s.customer_id JOIN incident_tickets i ON c.customer_id = i.customer_id WHERE c.tier = 'Enterprise' AND c.status = 'active' AND s.payment_status = 'paid' AND i.reported_at >= '2024-02-01' AND i.reported_at < '2024-03-01' AND i.status = 'resolved' GROUP BY c.customer_id, c.company_name, s.billing_cycle, s.monthly_rate HAVING SUM(i.downtime_minutes) > 0;"
}

